// B作成。通常Runtime.reopenの既存結果・状態境界だけを合成履歴で検査する。
function samePubReopenFixture(verdict){
 const v=samePubDecode(),e=v.rows.at(-1),body=samePubAPI.nativeJSONClone(v.objects[e.payload.artifact]);assert.equal(e.payload.node,'Z01_CLOSE');body.verdict=verdict;const ref=samePubAPI.nativeDigest(body);v.objects[ref]=body;e.payload.artifact=ref;e.payload.verdict=verdict;samePubReseal(v);
 return{v,payload:{node:'Z01_CLOSE',previous_result:ref,reason:'TEST_FIXTURE 実未解決結果の再分析',evidence_refs:['TEST_FIXTURE_FAILURE']}};
}
function samePubAddReopenEvent(v,kind,payload){const last=v.rows.at(-1),e={seq:last.seq+1,previous:last.hash,id:'TEST_FIXTURE_REOPEN_EXTENSION_'+v.rows.length,time:last.time+1,kind,work:'W-TECH-QF01-CHECKPOINT-PUBLISHER-20261122',payload};e.hash=samePubAPI.nativeDigest(e);v.rows.push(e);}
test('same PUB current PASSED Z01 cannot be reopened by a rehashed suffix',()=>{
 const {v,payload}=samePubReopenFixture('PASS');samePubAddReopenEvent(v,'result_reopened',payload);assert.throws(()=>samePubRead(v),/PUB_REVISION_REOPEN_ONLY_ACTUAL_CURRENT_FAILED_OR_BLOCKED_RESULT/);
});
test('same PUB actual FAILED and BLOCKED result can be reopened',()=>{
 for(const verdict of ['FAIL','NEEDS_REVIEW']){const {v,payload}=samePubReopenFixture(verdict);samePubAddReopenEvent(v,'result_reopened',payload);const current=samePubRead(v).current;assert.equal(current.state.results.Z01_CLOSE,undefined);assert.equal(current.resultEvents.Z01_CLOSE,undefined);}
});
test('same PUB reopen requires actual previous result registered evidence known node and current input',()=>{
 for(const variant of ['previous','unregistered','unknown-node','stale-input']){const {v,payload}=samePubReopenFixture('FAIL');if(variant==='previous')payload.previous_result='0'.repeat(64);else if(variant==='unregistered')payload.evidence_refs=['TEST_FIXTURE_UNREGISTERED'];else if(variant==='unknown-node')payload.node='TEST_FIXTURE_UNKNOWN_NODE';else samePubAddReopenEvent(v,'issue',{id:'TEST_FIXTURE_NEW_ISSUE'});samePubAddReopenEvent(v,'result_reopened',payload);assert.throws(()=>samePubRead(v),/PUB_REVISION_REOPEN_ONLY_ACTUAL_CURRENT_FAILED_OR_BLOCKED_RESULT/);}
});

test('same PUB reopen keeps expired claim BLOCKED priority over an existing stale PASS result',()=>{
 const v=samePubDecode();samePubAddReopenEvent(v,'issue',{id:'TEST_FIXTURE_REOPEN_INPUT_CHANGE'});const frame=samePubRead(v).current,old=frame.state.results.L01_LEARNING,input=samePubAPI.publisherRevisionInput(frame.state,v.nodes.L01_LEARNING);assert.notEqual(old.input_hash,input);
 samePubAddReopenEvent(v,'claimed',{node:'L01_LEARNING',actor:'TEST_FIXTURE_REOPEN_EXECUTOR',input_hash:input,task_id:samePubAPI.nativeDigest({work:frame.state.plan.work_id,node:'L01_LEARNING',input_hash:input}),token:'a'.repeat(32),expires_at:v.rows.at(-1).time+1});
 samePubAddReopenEvent(v,'result_reopened',{node:'L01_LEARNING',previous_result:old.artifact,reason:'TEST_FIXTURE 期限切れclaimの通常BLOCKED境界',evidence_refs:['TEST_FIXTURE_FAILURE']});const current=samePubRead(v).current;assert.equal(current.state.results.L01_LEARNING,undefined);assert.ok(current.state.claims.L01_LEARNING);
});

test('same PUB reopen may target a previous-interval result before any current result event',()=>{
 const v=samePubDecode(),i=samePubIndex(v,'result','T01_ANALYSIS',true);v.rows=v.rows.slice(0,i);const frame=samePubRead(v).current;assert.equal(frame.resultEvents.T01_ANALYSIS,undefined);assert.ok(frame.state.results.T01_ANALYSIS);const claim=frame.state.claims.T01_ANALYSIS;
 samePubAddReopenEvent(v,'result_reopened',{node:'T01_ANALYSIS',previous_result:frame.state.results.T01_ANALYSIS.artifact,reason:'TEST_FIXTURE 前revision結果と現claimの通常BLOCKED境界',evidence_refs:['TEST_FIXTURE_FAILURE']});v.rows.at(-1).time=claim.expires_at+1;samePubReseal(v);const current=samePubRead(v).current;assert.equal(current.state.results.T01_ANALYSIS,undefined);assert.equal(current.resultEvents.T01_ANALYSIS,undefined);assert.ok(current.state.claims.T01_ANALYSIS);
});

// TEST_FIXTURE: public code-derived normal650 workflow; no actual Native/adoption payload.
const cpNormal650WorkflowFixtureBase64='';
function cpNormal650WorkflowFixture(){const raw=gunzipSync(Buffer.from(cpNormal650WorkflowFixtureBase64,'base64'),{maxOutputLength:300000});assert.equal(createHash('sha256').update(raw).digest('hex'),cpProduction650Fixed.normalWorkflowSHA256);return raw.toString('utf8');}
test('checkpoint TEST_FIXTURE normal650 producer keeps current source roles Linux319 and frozen graph',()=>{const text=cpNormal650WorkflowFixture(),expected={profile:'production-650',productionSource:cpProduction650Fixed.sourceSHA,testedSource:cpProduction650Fixed.sourceSHA};assert.equal(cpAssertProductionWorkflowSource(text,expected),cpProduction650Fixed.sourceSHA);assert.equal(cpAssertPreservedWorkflow(text,expected),true);});
test('checkpoint TEST_FIXTURE normal650 stale duplicate roles and current Linux pin mutations reject',()=>{const text=cpNormal650WorkflowFixture(),expected={profile:'production-650',productionSource:cpProduction650Fixed.sourceSHA,testedSource:cpProduction650Fixed.sourceSHA},sections=cpProductionWorkflowSections(text);for(const name of ['build','qa','attest','publish','hosted']){const job=sections.jobs[name];assert.throws(()=>cpAssertProductionWorkflowSource(text.replace(job,job.replace('SOURCE_SHA: '+expected.productionSource,'SOURCE_SHA: '+'0'.repeat(40))),expected));assert.throws(()=>cpAssertProductionWorkflowSource(text.replace(job,job.replace('SOURCE_SHA: '+expected.productionSource,'SOURCE_SHA: '+expected.productionSource+'\n      SOURCE_SHA: '+expected.productionSource)),expected));}for(const [key,value]of [['CHECKPOINT_CURRENT_TEST_COUNT','319'],['CHECKPOINT_TARGET_TEST_RUNTIME_SHA256',cpProduction650Fixed.targetRuntimeSHA256]]){const job=sections.jobs.checkpoint_linux,bad=job.replace(key+': '+value,key+': '+(key.endsWith('COUNT')?'269':'0'.repeat(64)));assert.notEqual(bad,job);assert.throws(()=>cpAssertProductionWorkflowSource(text.replace(job,bad),expected));}});
